fn report_resolution(
    mode: &str,
    submitted: u64,
    resolved: &str,
    assigned_idx: Option<usize>,
    decided: Option<Vec<LogEntry<TestEntry>>>,
    extra: &[(&str, String)],
) {
    let mut fields: Vec<(&str, String)> = vec![
        ("mode", q(mode)),
        ("origin", n(1)),
        ("submitted_value", submitted.to_string()),
        ("resolved", q(resolved)),
    ];
